void getAlphaFromTrainSet_out2(float *tolerance, float *C, int *d, int *dim, float *eps)
{
    (*tolerance) = 0.001;
    (*C) = 0.05;
    (*d) = -1;
    (*dim) = 256;
    (*eps) = 0.001;
}

void getAlphaFromTrainSet_out3(int *ret)
{
    (*ret) = 0;
}

void getAlphaFromTrainSet_out4_out0(float *b)
{
    b[0] = 0;
}

void getAlphaFromTrainSet_out4_out1(int *ExamineAll, int *cnt, int *NumChanged)
{
    (*ExamineAll) = 1;
    (*cnt) = 0;
    (*NumChanged) = 0;
}

void getAlphaFromTrainSet_out4_out2_out0(int *cnt, int *NumChanged, int *decomp_0, int *ExamineAll)
{
    (*cnt) = (*cnt) + 1;
    (*NumChanged) = 0;
    (*decomp_0) = (*ExamineAll) == 1;
}

void getAlphaFromTrainSet_out4_out2_out1_out0_out0(int *NumChanged, int *ret)
{
    (*NumChanged) = (*NumChanged) + (*ret);
}

void getAlphaFromTrainSet_out4_out2_out1_out0(int *ret, int *i, F2D **a, float *b, float *C, F2D **e, F2D *X, F2D **Y,
                                              float *tolerance, int *N, float *eps, int *dim, int *NumChanged)
{
    examineExample_rep0((*i), (*a), b, (*C), (*e), X, (*Y), (*tolerance), (*N), (*eps), (*dim), ret);
    getAlphaFromTrainSet_out4_out2_out1_out0_out0(NumChanged, ret);
}

void getAlphaFromTrainSet_out4_out2_out1(int *i, int *N, int *ret, F2D **a, float *b, float *C, F2D **e, F2D *X,
                                         F2D **Y, float *tolerance, float *eps, int *dim, int *NumChanged)
{
    for ((*i) = 0; (*i) < (*N); (*i)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        getAlphaFromTrainSet_out4_out2_out1_out0(ret, i, a, b, C, e, X, Y, tolerance, N, eps, dim, NumChanged);
    }
}

void getAlphaFromTrainSet_out4_out2_out2_out0_out0(F2D **a, int *i, float *C, int *decomp_3)
{
    int decomp_1;
    int decomp_2;
    decomp_1 = (*a)->data[(*i)] > 0;
    decomp_2 = (*a)->data[(*i)] < (*C);
    (*decomp_3) = decomp_1 && decomp_2;
}

void getAlphaFromTrainSet_out4_out2_out2_out0_out1_out0(int *NumChanged, int *ret)
{
    (*NumChanged) = (*NumChanged) + (*ret);
}

void getAlphaFromTrainSet_out4_out2_out2_out0_out1(int *ret, int *i, F2D **a, float *b, float *C, F2D **e, F2D *X,
                                                   F2D **Y, float *tolerance, int *N, float *eps, int *dim,
                                                   int *NumChanged)
{
    examineExample_rep1((*i), (*a), b, (*C), (*e), X, (*Y), (*tolerance), (*N), (*eps), (*dim), ret);
    getAlphaFromTrainSet_out4_out2_out2_out0_out1_out0(NumChanged, ret);
}

void getAlphaFromTrainSet_out4_out2_out2_out0(F2D **a, int *i, float *C, int *ret, float *b, F2D **e, F2D *X, F2D **Y,
                                              float *tolerance, int *N, float *eps, int *dim, int *NumChanged)
{
    int decomp_3;
    getAlphaFromTrainSet_out4_out2_out2_out0_out0(a, i, C, &decomp_3);
    if (decomp_3)
    {
        getAlphaFromTrainSet_out4_out2_out2_out0_out1(ret, i, a, b, C, e, X, Y, tolerance, N, eps, dim, NumChanged);
    }
}

void getAlphaFromTrainSet_out4_out2_out2(int *i, int *N, F2D **a, float *C, int *ret, float *b, F2D **e, F2D *X,
                                         F2D **Y, float *tolerance, float *eps, int *dim, int *NumChanged)
{
    for ((*i) = 0; (*i) < (*N); (*i)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        getAlphaFromTrainSet_out4_out2_out2_out0(a, i, C, ret, b, e, X, Y, tolerance, N, eps, dim, NumChanged);
    }
}

void getAlphaFromTrainSet_out4_out2_out3(int *ExamineAll, int *NumChanged)
{
    int decomp_4;
    decomp_4 = (*ExamineAll) == 1;
    if (decomp_4)
    {
        (*ExamineAll) = 0;
    }
    else
    {
        int decomp_5;
        decomp_5 = (*NumChanged) == 0;
        if (decomp_5)
        {
            (*ExamineAll) = 1;
        }
    }
}

void getAlphaFromTrainSet_out4_out2(int *cnt, int *NumChanged, int *ExamineAll, int *i, int *N, int *ret, F2D **a,
                                    float *b, float *C, F2D **e, F2D *X, F2D **Y, float *tolerance, float *eps,
                                    int *dim)
{
    int decomp_0;
    getAlphaFromTrainSet_out4_out2_out0(cnt, NumChanged, &decomp_0, ExamineAll);
    if (decomp_0)
    {
        getAlphaFromTrainSet_out4_out2_out1(i, N, ret, a, b, C, e, X, Y, tolerance, eps, dim, NumChanged);
    }
    else
    {
        getAlphaFromTrainSet_out4_out2_out2(i, N, a, C, ret, b, e, X, Y, tolerance, eps, dim, NumChanged);
    }
    getAlphaFromTrainSet_out4_out2_out3(ExamineAll, NumChanged);
}

void getAlphaFromTrainSet_out4_out3(int *r, int *N, F2D *a_result, int *iter, F2D **a, F2D *b_result, float *b)
{
    for ((*r) = 0; (*r) < (*N); (*r)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        a_result->data[((*iter)) * a_result->width + ((*r))] = (*a)->data[(*r)];
    }
    b_result->data[(*iter)] = b[0];
}

void getAlphaFromTrainSet_out4(F2D **Y, F2D *trn1, F2D *trn2, int *iter, int *N, int *iterations, F2D **a, float *b,
                               F2D **e, int *ExamineAll, int *cnt, int *NumChanged, int *i, int *ret, float *C, F2D *X,
                               float *tolerance, float *eps, int *dim, int *r, F2D *a_result, F2D *b_result)
{
    usps_read_partial_rep0(trn1, trn2, (*iter), 0, (*N) / (*iterations), (*iterations), Y);
    fSetArray_rep0((*N), 1, 0, a);
    getAlphaFromTrainSet_out4_out0(b);
    fSetArray_rep1((*N), 1, 0, e);
    getAlphaFromTrainSet_out4_out1(ExamineAll, cnt, NumChanged);
    while ((*NumChanged) > 0 || (*ExamineAll) == 1)
    {
#pragma HLS loop_tripcount max = 5 min = 9
        getAlphaFromTrainSet_out4_out2(cnt, NumChanged, ExamineAll, i, N, ret, a, b, C, e, X, Y, tolerance, eps, dim);
    }
    getAlphaFromTrainSet_out4_out3(r, N, a_result, iter, a, b_result, b);
    fFreeHandle_rep0((*Y));
    fFreeHandle_rep1((*e));
    fFreeHandle_rep2((*a));
}

void getAlphaFromTrainSet_out5(alphaRet *alpha, float *C, int *d, int *dim, float *eps, F2D *a_result, F2D *b_result,
                               F2D *a, float *b, F2D *X, float *tolerance)
{
    alpha->C = (*C);
    alpha->d = (*d);
    alpha->dim = (*dim);
    alpha->eps = (*eps);
    alpha->a_result = a_result;
    alpha->b_result = b_result;
    alpha->a = a;
    alpha->b = b[0];
    alpha->X = X;
    alpha->tolerance = (*tolerance);
    alpha->ret;
}

void getAlphaFromTrainSet_sw(int N, F2D *trn1, F2D *trn2, int iterations, alphaRet **rtr_val)
{
    float tolerance;
    float C;
    float eps;
    float *b;
    F2D *a_result;
    F2D *b_result;
    int NumChanged;
    int r;
    int ExamineAll;
    int cnt;
    int d;
    int dim;
    int ret;
    int iter;
    int i;
    F2D *X;
    F2D *Y;
    F2D *a;
    F2D *e;
    alphaRet *alpha;
#pragma clava malloc_size max = 4 min = 4 avg = 4
    b = malloc(sizeof(float));
#pragma clava malloc_size max = 80 min = 80 avg = 80
    alpha = (alphaRet *)malloc(sizeof(alphaRet));
    getAlphaFromTrainSet_out2(&tolerance, &C, &d, &dim, &eps);
    fSetArray_rep2(iterations, N, 0, &a_result);
    fSetArray_rep3(iterations, 1, 0, &b_result);
    getAlphaFromTrainSet_out3(&ret);
    usps_read_partial_rep1(trn1, trn2, 0, 1, (N / iterations), iterations, &X);
    for (iter = 0; iter < iterations; iter++)
    {
#pragma HLS loop_tripcount max = 10 min = 10
        getAlphaFromTrainSet_out4(&(Y), trn1, trn2, &iter, &N, &iterations, &(a), b, &(e), &ExamineAll, &cnt,
                                  &NumChanged, &i, &ret, &C, X, &tolerance, &eps, &dim, &r, a_result, b_result);
    }
    getAlphaFromTrainSet_out5(alpha, &C, &d, &dim, &eps, a_result, b_result, a, b, X, &tolerance);
    free(b);
    *rtr_val = alpha;
}

static void magic_timing_begin(unsigned int *cycles)
{
    struct timespec ts;
    clock_gettime(4, &ts);
    cycles[0] = ts.tv_nsec;
    cycles[1] = ts.tv_sec;
}

unsigned int *photonEndTiming()
{
    unsigned int *array;
#pragma clava malloc_size max = 8 min = 8 avg = 8
    array = (unsigned int *)malloc(sizeof(unsigned int) * 2);
    magic_timing_begin(array);

    return array;
}

void photonPrintTiming(unsigned int *elapsed)
{
    if (elapsed[1] == 0)
    {
        printf("Cycles elapsed\t\t- %u\n\n", elapsed[0]);
    }
    else
    {
        printf("Cycles elapsed\t\t- %u%u\n\n", elapsed[1], elapsed[0]);
    }
}

unsigned int *photonReportTiming(unsigned int *startCycles, unsigned int *endCycles)
{
    unsigned int *elapsed;
#pragma clava malloc_size max = 8 min = 8 avg = 8
    elapsed = (unsigned int *)malloc(sizeof(unsigned int) * 2);
    unsigned long long start = (((unsigned long long)0x0) | startCycles[0]) << 32 | startCycles[1];
    unsigned long long end = (((unsigned long long)0x0) | endCycles[0]) << 32 | endCycles[1];
    unsigned long long diff = end - start;
    elapsed[0] = (unsigned int)(diff >> 32);
    elapsed[1] = (unsigned int)(diff & 0xffffffff);

    return elapsed;
}

unsigned int *photonStartTiming()
{
    unsigned int *array;
#pragma clava malloc_size max = 8 min = 8 avg = 8
    array = (unsigned int *)malloc(sizeof(unsigned int) * 2);
    magic_timing_begin(array);

    return array;
}

