F2D *readFile(char *fileName)
{
    FILE *fp;
    F2D *fill;
    float temp;
    int rows, cols;
    int i, j;
    fp = fopen(fileName, "r");
    if (fp == nullptr)
    {
        printf("Error in file %s\n", fileName);

        return nullptr;
    }
    fscanf(fp, "%d", &cols);
    fscanf(fp, "%d", &rows);
    fSetArray_rep4(rows, cols, 0, &fill);
    for (i = 0; i < rows; i++)
    {
        for (j = 0; j < cols; j++)
        {
            fscanf(fp, "%f", &(fill->data[(i)*fill->width + (j)]));
        }
    }
    fclose(fp);

    return fill;
}

void svm_out0(F2D **a_result, alphaRet **alpha, F2D **b_result)
{
    (*a_result) = (*alpha)->a_result;
    (*b_result) = (*alpha)->b_result;
}

void svm_out1_out1(int *j, int *N, F2D **Yoffset, int *i, F2D *temp)
{
    for ((*j) = 0; (*j) < (*N); (*j)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        (*Yoffset)->data[((*i)) * (*Yoffset)->width + ((*j))] = temp->data[(*j)];
    }
}

void svm_out1(F2D *trn1, F2D *trn2, int *i, int *N, int *iter, int *j, F2D **Yoffset)
{
    F2D *temp;
    usps_read_partial_rep2(trn1, trn2, (*i), 0, (*N) / (*iter), (*iter), &temp);
    svm_out1_out1(j, N, Yoffset, i, temp);
    fFreeHandle_rep6(temp);
}

void svm_out2_out0(float *maxs)
{
    (*maxs) = 0;
}

void svm_out2_out1_out0_out0(int *decomp_0, F2D **a_result, int *i, int *j)
{
    (*decomp_0) = (*a_result)->data[((*i)) * (*a_result)->width + ((*j))] > 0;
}

void svm_out2_out1_out0_out1_out0(F2D **X, alphaRet **alpha)
{
    (*X) = (*alpha)->X;
}

void svm_out2_out1_out0_out1_out1(float *_d0_0, F2D **a_result, int *i, int *j, F2D **Yoffset)
{
    (*_d0_0) =
        (*a_result)->data[((*i)) * (*a_result)->width + ((*j))] * (*Yoffset)->data[((*i)) * (*Yoffset)->width + ((*j))];
}

void svm_out2_out1_out0_out1_out2(float *_d0_0, float *_d0_1, F2D **s, int *i)
{
    float _d0_2;
    float _d0_3;
    _d0_2 = (*_d0_0) * (*_d0_1);
    _d0_3 = (*s)->data[(*i)] + _d0_2;
    (*s)->data[(*i)] = _d0_3;
}

void svm_out2_out1_out0_out1(alphaRet **alpha, int *j, F2D **Xtst, int *n, F2D **a_result, int *i, F2D **Yoffset,
                             int *dim, F2D **s)
{
    F2D *X;
    F2D *XtstTemp;
    F2D *Xtemp;
    float _d0_1;
    float _d0_0;
    svm_out2_out1_out0_out1_out0(&(X), alpha);
    fDeepCopyRange_rep0(X, (*j), 1, 0, X->width, &Xtemp);
    fDeepCopyRange_rep1((*Xtst), (*n), 1, 0, (*Xtst)->width, &XtstTemp);
    svm_out2_out1_out0_out1_out1(&_d0_0, a_result, i, j, Yoffset);
    polynomial_rep9(3, Xtemp, XtstTemp, (*dim), &_d0_1);
    svm_out2_out1_out0_out1_out2(&_d0_0, &_d0_1, s, i);
    fFreeHandle_rep7(Xtemp);
    fFreeHandle_rep8(XtstTemp);
}

void svm_out2_out1_out0(F2D **a_result, int *i, int *j, alphaRet **alpha, F2D **Xtst, int *n, F2D **Yoffset, int *dim,
                        F2D **s)
{
    int decomp_0;
    svm_out2_out1_out0_out0(&decomp_0, a_result, i, j);
    if (decomp_0)
    {
        svm_out2_out1_out0_out1(alpha, j, Xtst, n, a_result, i, Yoffset, dim, s);
    }
}

void svm_out2_out1_out1(F2D **s, int *i, F2D **b_result, float *maxs)
{
    int decomp_1;
    (*s)->data[(*i)] = (*s)->data[(*i)] - (*b_result)->data[(*i)];
    decomp_1 = (*s)->data[(*i)] > (*maxs);
    if (decomp_1)
    {
        (*maxs) = (*s)->data[(*i)];
    }
}

void svm_out2_out1(int *j, int *N, F2D **a_result, int *i, alphaRet **alpha, F2D **Xtst, int *n, F2D **Yoffset,
                   int *dim, F2D **s, F2D **b_result, float *maxs)
{
    for ((*j) = 0; (*j) < (*N); (*j)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        svm_out2_out1_out0(a_result, i, j, alpha, Xtst, n, Yoffset, dim, s);
    }
    svm_out2_out1_out1(s, i, b_result, maxs);
}

void svm_out2_out2(F2D **result, int *n, float *maxs)
{
    (*result)->data[(*n)] = (*maxs);
}

void svm_out2(F2D **s, int *iter, int *i, int *j, int *N, F2D **a_result, alphaRet **alpha, F2D **Xtst, int *n,
              F2D **Yoffset, int *dim, F2D **b_result, F2D **result)
{
    float maxs;
    svm_out2_out0(&maxs);
    fSetArray_rep5((*iter), 1, 0, s);
    for ((*i) = 0; (*i) < (*iter); (*i)++)
    {
#pragma HLS loop_tripcount max = 10 min = 10
        svm_out2_out1(j, N, a_result, i, alpha, Xtst, n, Yoffset, dim, s, b_result, &maxs);
    }
    fFreeHandle_rep9((*s));
    svm_out2_out2(result, n, &maxs);
}

void kernel_hw_bridge(int N, F2D *trn1, F2D *trn2, int iterations, alphaRet **rtr_val);
void svm(alphaRet **alpha, int *N, F2D *trn1, F2D *trn2, int *iter, F2D **a_result, F2D **b_result, F2D **Yoffset,
         F2D **Xtst, F2D *tst1, F2D *tst2, int *Ntst, F2D **Ytst, int *i, int *j, F2D **result, int *n, F2D **s,
         int *dim)
{
    if (getenv("OFFLOAD") != nullptr || getenv("OFFLOAD_SIM") != nullptr)
    {
        kernel_hw_bridge((*N), trn1, trn2, (*iter), alpha);
    }
    else
    {
        getAlphaFromTrainSet_sw((*N), trn1, trn2, (*iter), alpha);
    }
    svm_out0(a_result, alpha, b_result);
    printf("a_result[0] = %f, a_result[1] = %f\n", (*a_result)->data[0], (*a_result)->data[1]);
    printf("X[0] = %f, X[1] = %f\n", (*alpha)->X->data[0], (*alpha)->X->data[1]);
    fSetArray_rep6((*iter), (*N), 0, Yoffset);
    usps_read_partial_rep3(tst1, tst2, -1, 1, (*Ntst) / (*iter), (*iter), Xtst);
    usps_read_partial_rep4(tst1, tst2, -1, 0, (*Ntst) / (*iter), (*iter), Ytst);
    for ((*i) = 0; (*i) < (*iter); (*i)++)
    {
#pragma HLS loop_tripcount max = 10 min = 10
        svm_out1(trn1, trn2, i, N, iter, j, Yoffset);
    }
    fSetArray_rep7((*Ntst), 1, 0, result);
    for ((*n) = 0; (*n) < (*Ntst); (*n)++)
    {
#pragma HLS loop_tripcount max = 100 min = 100
        svm_out2(s, iter, i, j, N, a_result, alpha, Xtst, n, Yoffset, dim, b_result, result);
    }
}

int main(int argc, char *argv[])
{
    int iter, N, Ntst, i, j, k, n;
    F2D *trn1, *tst1, *trn2, *tst2, *Yoffset;
    alphaRet *alpha;
    F2D *a_result, *result;
    F2D *s;
    F2D *b_result;
    F2D *Xtst, *Ytst;
    unsigned int *start, *stop, *elapsed;
    char im1[256];
    int dim = 256;
    N = 100;
    Ntst = 100;
    iter = 10;
    printf("Input size\t\t- (%dx%dx%d)\n", N, Ntst, iter);
    if (argc < 2)
    {
        printf("We need input image path\n");

        return -1;
    }
    sprintf(im1, "%s/d16trn_1.txt", argv[1]);
    trn1 = readFile(im1);
    sprintf(im1, "%s/d16trn_2.txt", argv[1]);
    trn2 = readFile(im1);
    sprintf(im1, "%s/d16tst_1.txt", argv[1]);
    tst1 = readFile(im1);
    sprintf(im1, "%s/d16tst_2.txt", argv[1]);
    tst2 = readFile(im1);
    start = photonStartTiming();
    svm(&(alpha), &N, trn1, trn2, &iter, &(a_result), &(b_result), &(Yoffset), &(Xtst), tst1, tst2, &Ntst, &(Ytst), &i,
        &j, &(result), &n, &(s), &dim);
    stop = photonEndTiming();
    int _scope0_ret = 0;
    float _scope0_tol = 0.5;
    // fWriteMatrix(result, argv[1]);
    _scope0_ret = fSelfCheck(result, argv[1], _scope0_tol);
    if (_scope0_ret == -1)
    {
        printf("Error in SVM\n");
    }
    fFreeHandle_rep10(trn1);
    fFreeHandle_rep11(tst1);
    fFreeHandle_rep12(trn2);
    fFreeHandle_rep13(tst2);
    fFreeHandle_rep14(Yoffset);
    fFreeHandle_rep15(result);
    fFreeHandle_rep16(alpha->a_result);
    fFreeHandle_rep17(alpha->b_result);
    fFreeHandle_rep18(alpha->X);
    free(alpha);
    fFreeHandle_rep19(Xtst);
    fFreeHandle_rep20(Ytst);
    elapsed = photonReportTiming(start, stop);
    photonPrintTiming(elapsed);
    free(start);
    free(stop);
    free(elapsed);

    return 0;
}

